# ----- the Dickey-Fuller t-ratio (Bao, Broda and Kan, "Inversion formulas and saddlepoint
# expansions for Studentized means", Section 7)

# cosh(mu), (1 - cosh mu)/z and sinh(mu)/mu with mu = sqrt(z), as entire functions of z, for
# numbers and Taylor polynomials: by their power series near z = 0 (where (1 - cosh mu)/z
# cancels), by cosh and sinh of the real square root for z > 0, and by cos and sin for z < 0.
df_const(z::TaylorN) = constant_term(z)
df_const(z::Number) = z
function df_entire_csq(z, nser::Integer)
    z0 = df_const(z)
    T = float(real(typeof(z0)))
    if abs(z0) < T(1//100)
        # C = sum z^j/(2j)!, S = sum z^j/(2j+1)!, Q = -sum z^j/(2j+2)!  (Horner)
        C = zero(z) + 1/factT(T, 2nser); S = zero(z) + 1/factT(T, 2nser + 1); Q = zero(z) - 1/factT(T, 2nser + 2)
        for j in nser-1:-1:0
            C = C*z + 1/factT(T, 2j); S = S*z + 1/factT(T, 2j + 1); Q = Q*z - 1/factT(T, 2j + 2)
        end
        return C, Q, S
    elseif real(z0) > 0 && (z0 isa Real || imag(z0) == 0)
        mu = sqrt(z); C = cosh(mu); S = sinh(mu)/mu
    elseif z0 isa Real
        mu = sqrt(-z); C = cos(mu); S = sin(mu)/mu
    else
        mu = sqrt(z); C = cosh(mu); S = sinh(mu)/mu
    end
    return C, (1 - C)/z, S
end

"""
    dickey_fuller_cgf(model; c=0.0, window=8.0)

The joint cumulant generating function of ``(U, V)``, ``U = ∫\\tilde y\\,dy`` and
``V = ∫\\tilde y^2``, for the near-unit-root diffusion ``dy = c\\,y\\,dt + dW`` on ``[0, 1]`` with
``y(0) = 0``, where ``\\tilde y`` is ``y`` (`model = 1`, no deterministic terms), ``y`` demeaned
(`model = 2`, a constant) or ``y`` detrended (`model = 3`, a constant and a linear trend). The
limiting Dickey-Fuller ``t``-ratio is ``U/\\sqrt{V}``, so that [`studentized_tailprob`](@ref) and
[`studentized_density`](@ref) give its limiting distribution and density under the unit root
(`c = 0`) and under the local alternatives ``c < 0``. The functions are those of Nabeya and Tanaka
(1990) and Nabeya and Sørensen (1994): ``K(s, t) = -s/2 + e - \\log D(s, t)/2`` with ``D`` built
from ``\\cosh μ``, ``\\sinh μ/μ`` and ``(1 - \\cosh μ)/μ^2``, ``μ^2 = c^2 - 2t``, as entire
functions of ``μ^2``. Near ``μ^2 = 0``, for ``|μ^2| <`` `window`, ``D`` is evaluated by its
Taylor series in ``μ^2`` (its closed form divides by ``μ^2`` or ``μ^6`` and cancels there).
"""
function dickey_fuller_cgf(model::Integer; c::Real=0.0, window::Real=8.0)
    model in (1, 2, 3) || throw(ArgumentError("dickey_fuller_cgf: model must be 1, 2 or 3"))
    cc = c
    function K(t)
        s = t[1]; tt = t[2]
        T = float(real(typeof(df_const(s))))
        cT = T(cc)
        z = cT*cT - 2tt
        C, Q, S = df_entire_csq(z, 40)
        e = exp(cT)
        if model == 1
            D = C - (cT + s)*S
            return -s/2 - cT/2 - log(D)/2
        end
        lam = -s; lx = tt
        z0 = df_const(z)
        if model == 2
            if abs(z0) < window
                D = sum(D1_SERIES[j+1](lam, cT, T)*z^j for j in 0:length(D1_SERIES)-1)*e
            else
                A = 2*cT*cT*lam - 4*cT*lx - 2*lam*lam
                B = -cT^3 + cT*cT*lam - 2*lx - lam*lam
                D = (cT*cT*(1 - z*Q) + A*Q + B*S)/z*e
            end
        else
            if abs(z0) < window
                D = sum(D2_SERIES[j+1](lam, cT, T)*z^j for j in 0:length(D2_SERIES)-1)*e
            else
                c2, c3, c4, c5, c6, c7 = cT^2, cT^3, cT^4, cT^5, cT^6, cT^7
                P1 = c6 - 12*c4*lam + 2*lx*(-c4 + 12*c3 - 12*c2) + 48*lam*lam*(c2 - 3*cT + 3)
                P2 = (4*lam*(-c6 + 6*c4) + 16*lam*lam*(c4 - 3*c3 - 3*c2 + 18*cT - 18)
                      + 8*lx*(c5 - 3*c4 + c4*lam - 4*lam*lam*(c2 - 3*cT + 3)) + 16*lx*lx*(-c3 + 3*c2 - 6*cT + 6))
                P3 = (-c7 + lam*(c6 + 24*c4) + 4*lam*lam*(-c4 + 3*c3 - 27*c2 + 72*cT - 72)
                      + 2*lx*(c5 - 4*c4 - 12*c3 + 12*c2 - c4*lam + 4*lam*lam*(c2 - 3*cT + 3)) + 16*lx*lx*(c2 - 3*cT + 3))
                D = ((1 - z*Q)*P1 + Q*P2 + S*P3)/z^3*e
            end
        end
        return -s/2 - log(D)/2
    end
    return CGF(K, 2)
end
